package com.hbm.network.cargo.request;
import com.hbm.network.cargo.CargoDroneContent;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.sounds.*;
import net.minecraft.world.entity.player.*;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.level.block.state.BlockState;
public final class DroneDockEntity extends RequestContainerEntity {
 public static final int PATHING_DEPTH=10;public DroneDockEntity(BlockPos p,BlockState s){super(CargoRequestContent.DOCK_ENTITY.get(),p,s,9);}@Override public String sourceName(){return "container.droneDock";}
 public void serverTick(){networkTick();if(level==null||level.isClientSide||level.getGameTime()%20!=0||!hasDrone())return;var nodes=getAllLocalNodes((net.minecraft.server.level.ServerLevel)level,worldPosition.getX(),worldPosition.getZ(),5);var requests=new ArrayList<RequestNetwork.RequestNode>();var offers=new ArrayList<RequestNetwork.OfferNode>();for(var node:nodes){if(node instanceof RequestNetwork.RequestNode request)requests.add(request);if(node instanceof RequestNetwork.OfferNode offer)offers.add(offer);}attempt:for(int i=0;i<5;i++){Collections.shuffle(requests);Collections.shuffle(offers);RequestNetwork.RequestNode first=null;for(var request:requests)if(request.active&&!request.request.isEmpty()){first=request;break;}if(first!=null){var own=nodes.getMap().get(CargoHashedSet.positionHash(worldPosition.above()));var requested=first.request.get(level.random.nextInt(first.request.size()));outer:for(var offer:offers)for(var stack:offer.offer)if(offer.active&&!stack.isEmpty()&&requested.matches(stack)){if(tryEmbark(own,first,offer,requested,nodes))break attempt;break outer;}}}}
 public boolean tryEmbark(RequestNetwork.PathNode dock,RequestNetwork.RequestNode request,RequestNetwork.OfferNode offer,CargoRequestStack item,CargoHashedSet<RequestNetwork.PathNode> nodes){var a=generatePath(dock,offer,nodes);if(a==null)return false;var b=generatePath(offer,request,nodes);if(b==null)return false;var c=generatePath(request,dock,nodes);if(c==null)return false;for(int i=0;i<slots.size();i++)if(isDrone(slots.get(i))){removeItem(i,1);break;}var drone=new RequestDrone(CargoRequestContent.REQUEST_ENTITY.get(),level);drone.setPos(worldPosition.getX()+.5,worldPosition.getY()+1,worldPosition.getZ()+.5);for(var node:a)drone.program.add(node.pos);drone.program.add(offer.pos);drone.program.add(item);for(var node:b)drone.program.add(node.pos);drone.program.add(request.pos);drone.program.add(RequestDrone.DroneProgram.UNLOAD);for(var node:c)drone.program.add(node.pos);drone.program.add(dock.pos);drone.program.add(RequestDrone.DroneProgram.DOCK);level.addFreshEntity(drone);level.playSound(null,worldPosition.getX()+.5,worldPosition.getY()+.5,worldPosition.getZ()+.5,com.hbm.registry.HbmSounds.get("block.storageOpen"),SoundSource.BLOCKS,2,1);return true;}
 public List<RequestNetwork.PathNode> generatePath(RequestNetwork.PathNode start,RequestNetwork.PathNode end,CargoHashedSet<RequestNetwork.PathNode> local){if(start==null||end==null)return null;var paths=new ArrayList<List<RequestNetwork.PathNode>>();var init=new ArrayList<RequestNetwork.PathNode>();init.add(start);paths.add(init);outer:for(int i=0;i<PATHING_DEPTH;i++){int brake=1000;var newPaths=new ArrayList<List<RequestNetwork.PathNode>>();for(var oldPath:paths)for(var unsafe:oldPath.getLast().reachableNodes){var safe=local.getMap().get(unsafe.hashCode());if(safe!=null){var path=new ArrayList<>(oldPath);if(safe.hashCode()==end.hashCode()){path.removeFirst();return path;}path.add(safe);newPaths.add(path);}brake--;if(brake<=0)continue outer;}paths=newPaths;}return null;}
 public static boolean isDrone(net.minecraft.world.item.ItemStack stack){return stack.is(CargoDroneContent.drone(com.hbm.network.cargo.DroneItem.Kind.REQUEST));}public boolean hasDrone(){for(var stack:slots)if(isDrone(stack))return true;return false;}
 @Override public RequestNetwork.PathNode createNode(BlockPos pos){return new RequestNetwork.PathNode(pos,reachableNodes);}@Override public AbstractContainerMenu createMenu(int id,Inventory inv,Player player){return new CargoRequestMenu(id,inv,this,CargoRequestContent.Kind.DOCK);}
}
